const normalizePermissions = (input, role) => {
  if (String(role || "").trim().toLowerCase() === "production") {
    return {
      viewReport: false,
      viewScorecard: false,
      viewMaster: false,
      manageMaster: false,
      manageVendors: false,
      manageItems: false,
      viewPrl: false,
      prlProcess: false,
      prlImport: false,
      editSchedules: false,
      deleteRecords: false,
      importExport: false,
      useAI: false,
      manageUsers: false,
      resetAll: false,
      production: true,
    };
  }
  const base = defaultPermissionsByRole[role] || defaultPermissionsByRole.user;
  const normalized = { ...base };
  if (input && typeof input === "object") {
    for (const key of permissionKeys) {
      if (typeof input[key] === "boolean") normalized[key] = input[key];
    }
  }
  return normalized;
};

