app.post("/api/so-sessions/:id/finalize", authenticate, requirePermission("editSchedules"), async (req, res) => {
  const client = await pool.connect();
  try {
    const id = Number(req.params.id);
    if (!Number.isFinite(id)) {
      res.status(400).json({ error: "id tidak valid" });
      return;
    }
    await client.query("begin");
    const sessionResult = await client.query("select * from so_sessions where id = $1 for update", [id]);
    if (sessionResult.rows.length === 0) {
      await client.query("rollback");
      res.status(404).json({ error: "session tidak ditemukan" });
      return;
    }
    const session = sessionResult.rows[0];
    if (session.status === "POSTED") {
      await client.query("rollback");
      res.status(409).json({ error: "Session sudah POSTED." });
      return;
    }
    const itemsResult = await client.query(
      "select * from so_items where session_id = $1 for update",
      [id],
    );
    const referenceDoc = session.period ? `SO-${session.period}` : `SO-${id}`;
    for (const row of itemsResult.rows) {
      const actualQty = Number(row.actual_qty ?? row.book_qty ?? 0);
      const bookQty = Number(row.book_qty || 0);
      const difference = actualQty - bookQty;
      if (difference !== 0 && !row.reason) {
        await client.query("rollback");
        res.status(400).json({ error: `Reason wajib diisi untuk ${row.item_code}.` });
        return;
      }
      if (row.actual_qty === null || row.actual_qty === undefined) {
        await client.query(
          `update so_items set actual_qty = $1, difference = $2 where id = $3`,
          [actualQty, difference, row.id],
        );
      }
      await client.query(
        "update items set qty_on_hand = $1 where code = $2",
        [actualQty, row.item_code],
      );
      if (difference !== 0) {
        await logStockMovement(client, {
          itemCode: row.item_code,
          batchId: null,
          qty: Math.abs(difference),
          direction: difference > 0 ? "in" : "out",
          reason: "stock_opname",
        });
        await insertInventoryLedger(client, {
          itemCode: row.item_code,
          transactionType: "ADJUSTMENT_SO",
          referenceDoc,
          qtyIn: difference > 0 ? Math.abs(difference) : 0,
          qtyOut: difference < 0 ? Math.abs(difference) : 0,
          userId: req.user?.id || null,
          remarks: row.reason || null,
        });
      }
    }
    await client.query("update so_sessions set status = 'POSTED' where id = $1", [id]);
    await client.query("commit");
    void recordActivityNotification(pool, {
      userId: req.user?.id || null,
      module: "Stock Opname",
      severity: "success",
      title: `Stock Opname ${session.period || id} diposting.`,
      detail: `${itemsResult.rows.length} item terposting ke stock.`,
      entityType: "so_session",
      entityId: String(id),
      payload: { status: "POSTED", itemCount: itemsResult.rows.length },
    }).catch((error) => console.warn("SO notification failed:", error.message));
    res.json({ ok: true });
  } catch (error) {
    await client.query("rollback");
    res.status(500).json({ error: error.message });
  } finally {
    client.release();
  }
});

app.get("/api/stock-opname/sessions", authenticate, requirePermission("editSchedules"), async (req, res) => {
  try {
    const status = normalizeStockOpnameStatus(req.query.status || "");
    const locationFilter = String(req.query.location || "").trim().toLowerCase();
    const search = String(req.query.q || req.query.search || "").trim().toLowerCase();
    const filters = [];
    const values = [];
    if (status && status !== "draft") {
      values.push(status);
      filters.push(`lower(s.status) = $${values.length}`);
    }
    if (locationFilter) {
      values.push(`%${locationFilter}%`);
      filters.push(`(lower(coalesce(s.location_id, '')) like $${values.length} or lower(coalesce(s.location_name, '')) like $${values.length})`);
    }
    if (search) {
      values.push(`%${search}%`);
      filters.push(`(lower(coalesce(s.session_no, '')) like $${values.length} or lower(coalesce(s.notes, '')) like $${values.length})`);
    }
    const whereClause = filters.length ? `where ${filters.join(" and ")}` : "";
    const result = await pool.query(
      `
      select
        s.*,
        coalesce(count(distinct l.item_code), 0)::int as item_count,
        coalesce(count(l.id), 0)::int as line_count,
        coalesce(sum(case when coalesce(l.variance_qty, 0) <> 0 then 1 else 0 end), 0)::int as variance_count
      from stock_opname_sessions s
      left join stock_opname_lines l on l.session_id = s.id
      ${whereClause}
      group by s.id
      order by s.created_at desc, s.id desc
      `,
      values,
    );
    res.json(result.rows.map(mapStockOpnameSessionRow));
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

